      "Phòng khách sạn có vấn đề (điều hòa hỏng, ồn, mùi, không sạch). Đến lễ tân yêu cầu đổi phòng. 해요체 với receptionist; 하십시오체 nếu lên gặp manager. Cấu trúc: mô tả vấn đề CỤ THỂ (không generic), đề xuất giải pháp (không chỉ phàn nàn), giữ tone calm — Hàn customer service phản ứng tốt với specific facts, kém với emotional complaints.",
